package cn.zhuatech.projectagent.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
/**
 * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
 */
@Service public class ProjectActionExecutionService{/**
                                                     * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                     */
public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.baselineCurrent())b.add("项目范围与计划基线不是最新版本");if(!r.actionOwnerAssigned())b.add("行动责任人未指定");if(!r.executionAuthorityVerified())b.add("执行权限未验证");if(!r.budgetImpactApproved())b.add("预算影响未批准");if(!r.scheduleImpactAssessed())b.add("进度影响未评估");if(!r.riskAssessmentComplete())b.add("风险评估未完成");if(!r.dependenciesConfirmed())b.add("关键依赖未确认");if(r.externalCommitment()&&!r.externalCommunicationApproved())b.add("外部承诺未获批准");if(!r.finalApprovalComplete())b.add("Agent 行动审批未完成");if(!b.isEmpty()){a.add("阻断执行并转交项目经理与治理角色复核");return new Assessment(Decision.BLOCKED,b,a);}if(!r.rollbackReady()||!r.auditTrailEnabled()){if(!r.rollbackReady())a.add("准备撤销行动和恢复项目基线方案");if(!r.auditTrailEnabled())a.add("启用输入、建议、人工修改和执行结果审计");return new Assessment(Decision.COORDINATE,b,a);}a.add("批准行动执行并跟踪结果、偏差和责任闭环");return new Assessment(Decision.EXECUTE,b,a);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           */
public record Request(@NotBlank String actionId,boolean baselineCurrent,boolean actionOwnerAssigned,boolean executionAuthorityVerified,boolean budgetImpactApproved,boolean scheduleImpactAssessed,boolean riskAssessmentComplete,boolean dependenciesConfirmed,boolean externalCommitment,boolean externalCommunicationApproved,boolean rollbackReady,boolean auditTrailEnabled,boolean finalApprovalComplete){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            */
public record Assessment(Decision decision,List<String>blockers,List<String>actions){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  */
public enum Decision{EXECUTE,COORDINATE,BLOCKED}}
